package com.adib.maintenance;
import android.app.Activity;import android.os.*;import android.view.*;import android.widget.*;import java.util.*;
/** Defer a completion write for exactly five seconds. Cancel sends no request. */
final class CompletionUndo {
static final Handler handler=new Handler(Looper.getMainLooper());static final WeakHashMap<Activity,LinkedHashMap<String,Pending>> pending=new WeakHashMap<>();
static final class Pending {final Activity activity;final String id;final Runnable commit;Runnable timer;View bar;Pending(Activity a,String id,Runnable c){activity=a;this.id=id;commit=c;}}
static void schedule(Activity a,String id,Runnable commit){LinkedHashMap<String,Pending> map=pending.computeIfAbsent(a,k->new LinkedHashMap<>());if(map.containsKey(id))return;Pending p=new Pending(a,id,commit);map.put(id,p);LinearLayout bar=new LinearLayout(a);bar.setTag("completion-undo:"+id);bar.setGravity(Gravity.CENTER_VERTICAL);int d=(int)(a.getResources().getDisplayMetrics().density+.5f);bar.setPadding(12*d,8*d,8*d,8*d);bar.setBackground(HybridUi.rounded(0xff273344,12*d,0,0));TextView text=new TextView(a);text.setText("Tamamlanacaq · 5 saniyə");text.setTextColor(0xffedf3ff);text.setTextSize(15);text.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);bar.addView(text,new LinearLayout.LayoutParams(0,-2,1));Button cancel=new Button(a);cancel.setText("Ləğv et");cancel.setTextColor(0xffb9ceff);cancel.setBackgroundColor(android.graphics.Color.TRANSPARENT);cancel.setAllCaps(false);cancel.setMinHeight(44*d);cancel.setOnClickListener(v->cancel(a,id));bar.addView(cancel);FrameLayout decor=(FrameLayout)a.getWindow().getDecorView();FrameLayout.LayoutParams lp=new FrameLayout.LayoutParams(-1,-2,Gravity.BOTTOM);lp.setMargins(12*d,0,12*d,(72+(map.size()-1)*68)*d);decor.addView(bar,lp);p.bar=bar;p.timer=()->{remove(p);if(!a.isFinishing()&&!a.isDestroyed())commit.run();};handler.postDelayed(p.timer,5000);}
static void remove(Pending p){handler.removeCallbacks(p.timer);if(p.bar!=null&&p.bar.getParent() instanceof ViewGroup)((ViewGroup)p.bar.getParent()).removeView(p.bar);LinkedHashMap<String,Pending> map=pending.get(p.activity);if(map!=null){map.remove(p.id);if(map.isEmpty())pending.remove(p.activity);}}
static void cancel(Activity a,String id){LinkedHashMap<String,Pending> map=pending.get(a);Pending p=map==null?null:map.get(id);if(p!=null)remove(p);}
static void cancelAll(Activity a){LinkedHashMap<String,Pending> map=pending.get(a);if(map!=null)for(Pending p:new ArrayList<>(map.values()))remove(p);}
}
